// The galley: room two, and the test of whether the pipeline makes rooms or
// made one room.
//
// Everything here came through the same route as the dock — a backdrop
// generated from a composition-first prompt and then annotated, a cast
// generated by AutoSprite from the same style brief, atlases cut by
// sheet-cut.mjs, a puzzle graph the linter checks before the game runs. The
// only thing written by hand is what is written by hand in any adventure game:
// where the floor is, what you can click, and the jokes.
//
// The room's shape is the shape of its joke. The ship is the Errant Kipper.
// The kipper has erred.

import { walk, face, say, wait, run, play } from '../engine/script.js';
import * as art from '../art/paint.js';
import { makeGalleyHeat } from '../art/animate.js';

export const ROOM_W = 1280, ROOM_H = 720;

// The dependency graph. Seven nodes where the dock had five, and one of them
// is a combine rather than a fetch — which is the step that makes a puzzle
// feel like a puzzle rather than a shopping list.
export const PUZZLE = {
  start: ['hands'],
  goal: 'sailed',
  nodes: {
    'take-pepper':  { needs: ['hands'], gives: 'pepper', where: 'the mess table' },
    // A combine, which is what makes a puzzle a puzzle rather than a shopping
    // list — and it happens ON the bellows where they stand, because the verb
    // coin can put an item onto a thing in the room and has no way to put one
    // item onto another in the bag.
    'load-bellows': { needs: ['pepper'], gives: 'loaded-bellows', consumes: ['pepper'],
                      where: 'the bellows by the stove' },
    'sneeze-cat':   { needs: ['loaded-bellows'], gives: 'kipper-dropped',
                      consumes: ['loaded-bellows'], where: "the ship's cat, up on the barrels" },
    'take-kipper':  { needs: ['kipper-dropped'], gives: 'kipper', where: 'the galley floor' },
    'feed-cook':    { needs: ['kipper'], gives: 'dinner-on', consumes: ['kipper'],
                      where: 'Mervyn Pike' },
    'sail':         { needs: ['dinner-on'], gives: 'sailed', where: 'the mess bell' },
  },
};

// --- cast -------------------------------------------------------------------

