// --- the room ---------------------------------------------------------------

// Read off the generated painting. The floor runs the full width below the
// furniture, except at the left where the stove stands well forward of the
// back wall and eats the corner — so the walkable strip steps around it rather
// than letting her stroll through a lit firebox.
const WALK_GALLEY = [
  340, 528, 1268, 528, 1268, 712, 40, 712, 40, 646, 340, 646,
];

export function makeRoomDef(state, backdrop) {
  const heat = makeGalleyHeat();
  const whenStill = (fn) => (ctx, room) => { if (backdrop?.kind !== 'video') fn(ctx, room); };

  // The kipper, once the cat has been persuaded to part with it. Drawn rather
  // than generated: it exists for about ninety seconds of game and is a fish
  // on a floor, which is within the reach of a canvas path.
  const kipperLayer = {
    paint: (ctx) => {
      if (!state.get('kipper-dropped') || state.has('kipper')) return;
      ctx.save();
      ctx.translate(KIPPER_RECT[0] + KIPPER_RECT[2] / 2, KIPPER_RECT[1] + KIPPER_RECT[3] / 2);
      art.paintKipper(ctx);
      ctx.restore();
    },
  };

  return {
    id: 'galley',
    width: ROOM_W,
    height: ROOM_H,
    // A cramped interior: the floor is a shallow band, so the depth change
    // across it is small. Scaling it like the dock would make her shrink
    // walking four feet.
    scale: { y0: 528, s0: 0.85, y1: 712, s1: 1.12 },
    walk: [WALK_GALLEY],
    layers: [
      { paint: (ctx) => backdrop?.draw?.(ctx, ROOM_W, ROOM_H) },
      { paint: whenStill(heat) },
      kipperLayer,
    ],
    occluders: [],
    hotspots: HOTSPOTS(state),
  };
}

const KIPPER_RECT = [812, 556, 96, 40];

// --- things you can click ---------------------------------------------------

const H = (id, name, rect, at, verbs, extra = {}) => ({ id, name, rect, at, verbs, ...extra });

function HOTSPOTS(state) {
  return [
    H('stove', 'the galley stove', [27, 347, 280, 286], { x: 400, y: 662, facing: 'left' }, {
      look: function* (g) {
        yield say(g.player, "A cast-iron range with a fire in its belly and a pot on its head.");
        yield say(g.player, "The pot contains water. Only water. Bravely, it keeps boiling.", 3.6);
      },
      use: function* (g) { yield say(g.player, "I'd rather not put any part of myself in there."); },
    }),

    H('bellows', 'a pair of bellows', [167, 507, 120, 133], { x: 380, y: 668, facing: 'left' }, {
      look: function* (g) {
        if (g.state.has('loaded-bellows')) { yield say(g.player, "Loaded. Aimed. Waiting."); return; }
        yield say(g.player, "Leather bellows, for encouraging the fire.");
      },
      use: function* (g) {
        // The red herring, and the reason she has a bellows animation: the
        // obvious thing to do with bellows is work them, and the obvious thing
        // is not the answer.
        yield play(g.player, 'bellows');
        yield say(g.player, "The fire is delighted. The cat remains unmoved.", 3.2);
      },
      talk: function* (g) { yield say(g.player, "I've had better conversations, but not many."); },
    }, {
      useWith: {
        pepper: function* (g) {
          yield say(g.player, "Now. If I load these with pepper...", 2.6);
          yield play(g.player, 'bellows');
          yield run(() => { g.state.take('pepper'); g.state.give('loaded-bellows'); });
          yield say(g.player, "...I have invented a weapon.", 2.0);
        },
      },
    }),

    H('pot', 'the cooking pot', [140, 283, 127, 77], { x: 400, y: 662, facing: 'left' }, {
      look: function* (g) {
        yield say(g.player, "Boiling water. The recipe, I am told, calls for a fish.");
      },
    }),

    H('table', 'the mess table', [390, 343, 370, 184], { x: 560, y: 690, facing: 'back' }, {
      look: function* (g) {
        yield say(g.player, "Scrubbed to within an inch of its life. There is nothing on it.");
        yield say(g.player, "Which is, I gather, the entire problem.", 2.4);
      },
    }),

    H('pepper', 'a tin pepper pot', [556, 306, 44, 56], { x: 578, y: 686, facing: 'back' }, {
      look: function* (g) {
        yield say(g.player, "A dented tin pepper pot. The last seasoning aboard this ship.");
      },
      use: function* (g) {
        yield say(g.player, "I'll look after this.");
        yield run(() => g.state.give('pepper'));
      },
    }, { hidden: () => state.has('pepper') || state.has('loaded-bellows') }),

    H('bell', 'the mess bell', [530, 164, 84, 68], { x: 600, y: 682, facing: 'back' }, {
      look: function* (g) {
        yield say(g.player, "The mess bell. Ring it and the whole ship comes to dinner.");
        yield say(g.player, "Also, apparently, weighs anchor. Sailors are simple creatures.", 3.8);
      },
      use: function* (g) {
        if (!g.state.get('dinner-on')) {
          yield say(g.player, "It's a good foot above my reach, and I am not the cook.");
          return;
        }
        yield say(g.player, "Mervyn. Would you do the honours?", 2.2);
        yield say(g.pike, "Stand well back.", 1.6);
        yield walk(g.pike, g.room.walk, 620, 640);
        yield face(g.pike, 'right');
        yield play(g.pike, 'bell');
        yield say(g.pike, "DINNER!", 1.4);
        yield run(() => { g.state.set('sailed', true); g.onWorldChange(); });
        yield wait(0.4);
        yield say(g.player, "Somewhere above us, twelve men have started running.", 3.8);
      },
    }),

    H('barrels', 'a stack of barrels', [775, 308, 240, 210], { x: 900, y: 690, facing: 'back' }, {
      look: function* (g) {
        yield say(g.player, "Salt beef, salt pork, salt. A varied menu.");
      },
    }),

    H('lamp', 'a hanging lamp', [808, 165, 64, 100], { x: 850, y: 682, facing: 'back' }, {
      look: function* (g) { yield say(g.player, "It swings with the ship. Everything here does."); },
    }),

    H('door', 'a low doorway', [737, 163, 196, 317], { x: 835, y: 686, facing: 'back' }, {
      look: function* (g) { yield say(g.player, "Aft, into the dark, where the ship keeps its secrets and its rats."); },
      use: function* (g) { yield say(g.player, "One errand at a time."); },
    }),

    H('kipper', 'a kipper', KIPPER_RECT, { x: 860, y: 682, facing: 'back' }, {
      look: function* (g) {
        yield say(g.player, "A smoked herring, lightly cat.");
      },
      use: function* (g) {
        yield say(g.player, "The Errant Kipper, recovered.");
        yield run(() => g.state.give('kipper'));
      },
    }, { hidden: () => !state.get('kipper-dropped') || state.has('kipper') }),

    H('ladder', 'the companion ladder', [985, 80, 170, 455], { x: 1090, y: 690, facing: 'right' }, {
      look: function* (g) { yield say(g.player, "Up, and out, and back onto that miserable dock."); },
      use: function* (g) {
        if (!g.state.get('sailed')) {
          yield say(g.player, "Not until this fish business is settled.");
          return;
        }
        yield say(g.player, "Up on deck, then. Someone should watch where we're going.", 3.6);
        yield run(() => g.goTo('dock', 'galley'));
      },
    }, { exit: { to: 'dock', dir: 'up' } }),
  ];
}

// The moment the room is built around, reachable two ways.
//
// A player who has worked out that the cook wants the fish will either pick
// the line out of his conversation or simply use the fish on the cook, and an
// adventure game that only accepts one of those is an adventure game arguing
// with someone who has already solved it.
function* handOverKipper(g) {
  yield say(g.player, "I believe this belongs to your soup.", 2.6);
  yield say(g.pike, "...", 1.0);
  yield say(g.pike, "That's HIM. That's the kipper.", 2.2);
  yield run(() => g.state.take('kipper'));
  yield say(g.player, "He's a little chewed.", 1.6);
  yield say(g.pike, "He's been through a lot. So have I. Dinner is ON.", 3.6);
  yield run(() => { g.state.set('dinner-on', true); g.onWorldChange(); });
  yield say(g.player, "And the bell?", 1.4);
  yield say(g.pike, "The BELL!", 1.2);
}

// --- Mervyn -----------------------------------------------------------------

export const NPCS = {
  pike: {
    // He stands at his stove and never leaves it. Approach from his right,
    // which is the side the floor is on.
    approach: (a) => ({ x: a.x + 190, y: 664, facing: 'left' }),
    box: { w: 150, h: 330 },
    verbs: {
      look: function* (g) {
        if (g.state.get('dinner-on')) {
          yield say(g.player, "A man reunited with his fish. It is genuinely moving.");
          return;
        }
        yield say(g.player, "Nineteen stone of ship's cook, and every ounce of it sad.", 3.6);
      },
      use: function* (g) { yield say(g.player, "He's load-bearing. I'd need a crane."); },
    },
    useWith: {
      kipper: handOverKipper,
    },
    greeting: function* (g) {
      if (g.state.get('sailed')) { yield say(g.player, "Bon appetit, Mervyn."); return; }
      if (g.state.get('dinner-on')) { yield say(g.pike, "She's on. She's ON.", 1.8); return; }
      yield say(g.pike, "Dinner's off.", 1.3);
    },
    tree: (g) => {
      // Once the bell is rung he is a man with a full pot and nothing to
      // discuss. An empty tree closes the conversation.
      if (g.state.get('sailed')) return [];
      const said = (k) => g.state.get('galley-said-' + k);
      const opts = [];
      if (g.state.has('kipper')) opts.push({ id: 'give', text: "I believe this belongs to your soup. [give the kipper]" });
      if (!said('why')) opts.push({ id: 'why', text: "Why is dinner off?" });
      else opts.push({ id: 'why2', text: "About dinner." });
      if (said('why') && !said('bell')) opts.push({ id: 'bell', text: "Can't you just ring the bell anyway?" });
      if (said('why') && !said('cat')) opts.push({ id: 'cat', text: "Where is this cat now?" });
      opts.push({ id: 'bye', text: "I'll leave you to your grief." });
      return opts;
    },
    line: function* (g, opt) {
      const mark = (k) => g.state.set('galley-said-' + k, true);

      if (opt.id === 'give') { yield* handOverKipper(g); return; }

      if (opt.id === 'why' || opt.id === 'why2') {
        mark('why');
        yield say(g.pike, "We had one fish. ONE. A kipper. For twelve men.", 3.4);
        yield say(g.pike, "The cat has taken it up onto the barrels and is EATING IT AT ME.", 4.2);
        yield say(g.player, "At you.");
        yield say(g.pike, "At me. Slowly. Making eye contact.", 2.6);
        return;
      }

      if (opt.id === 'bell') {
        mark('bell');
        yield say(g.player, "Can't you just ring the bell anyway?");
        yield say(g.pike, "Ring the mess bell with no mess? On this ship?", 3.2);
        yield say(g.pike, "They'd come down that ladder like weather, and they'd find a pot of hot water.", 4.6);
        yield say(g.pike, "I'd not survive it. YOU'D not survive it.", 2.8);
        return;
      }

      if (opt.id === 'cat') {
        mark('cat');
        yield say(g.player, "Where is this cat now?");
        yield say(g.pike, "Up there. Where I can see him.", 2.2);
        yield say(g.pike, "I can't climb. I've tried. The barrels have opinions about my weight.", 4.4);
        return;
      }

      yield say(g.player, "I'll leave you to your grief.");
      yield say(g.pike, "Aye.", 0.9);
    },
  },

  cat: {
    approach: (a) => ({ x: a.x - 60, y: 690, facing: 'right' }),
    box: { w: 130, h: 110 },
    verbs: {
      look: function* (g) {
        if (g.state.get('kipper-dropped')) {
          yield say(g.player, "Gone. There is a cat-shaped hole in the air where he was.", 3.8);
          return;
        }
        yield say(g.player, "A ginger cat on a barrel, eating a kipper, watching a large man cry.", 4.6);
        yield say(g.player, "He is having the best day of his life.", 2.4);
      },
      use: function* (g) {
        if (g.state.get('kipper-dropped')) { yield say(g.player, "He's gone, and he's not coming back for an apology."); return; }
        yield say(g.player, "I'm not putting my hands anywhere near that.");
      },
      talk: function* (g) {
        if (g.state.get('kipper-dropped')) { yield say(g.player, "We've said everything we had to say."); return; }
        yield say(g.player, "Here, puss. Nice puss. Give me the fish, puss.", 3.4);
        yield say(g.cat, "...", 1.2);
        yield say(g.player, "He blinked at me. Slowly. It was an insult.", 3.0);
      },
    },
    useWith: {
      'loaded-bellows': function* (g) {
        yield say(g.player, "Sorry about this. You're a lovely cat and you've had it coming.", 4.2);
        yield play(g.player, 'bellows');
        yield run(() => g.state.take('loaded-bellows'));
        yield play(g.cat, 'sneeze');
        yield say(g.cat, "HRRRSHT!", 1.1);
        yield run(() => {
          g.state.set('kipper-dropped', true);
          g.cat.playClip('scarper');
          g.onWorldChange();
        });
        yield wait(0.7);
        yield run(() => { g.cat.visible = false; });
        yield say(g.player, "And there he goes, up the ladder, into legend.", 3.4);
        yield say(g.pike, "MY FISH!", 1.2);
      },
    },
  },
};

// Applied whenever the world changes, so a loaded save comes back to the same
// room rather than to the same flags.
export function applyState(room, state, g) {
  const cat = g?.actors?.cat;
  if (cat) cat.visible = !state.get('kipper-dropped');
}

// Where the player arrives, per door she came through.
export const SPAWN = {
  dock: { x: 1060, y: 690, facing: 'left' },
};
